import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>11 种滤镜，选择可不少。每种都会改变照片的氛围，选错了，好照片也可能看着廉价或者奇怪。</p>\n<p>把滤镜并排对比，是最快学会它们的办法。知道每种滤镜是干什么的，选择就快了，照片也有了统一风格。</p>\n<p>这篇文章会把 11 种风格直接对比：它们有什么不同、每种适合什么题材，以及怎么养成统一的滤镜习惯。看完对比，打开<a href=\"/zh/tupian-lvjing/\">图片滤镜</a>在同一张照片上挨个试一遍，差别立刻就清楚了。</p>\n<h2 id=\"why-compare-filters\">为什么要对比滤镜</h2>\n<p>小网格里滤镜看着差不多，全尺寸下差别却很大。小缩略图里看着暖的滤镜，主预览里可能把人脸变成橘色。</p>\n<p>同一张照片上对照，能清楚看到差别。同一张人像分别用复古、棕褐和黑白 Noir，看着像三张不同的照片。</p>\n<p>对比还能避免最常见的滤镜错误：每张照片用不同的滤镜。滤镜混着用的信息流看着很乱，统一的滤镜才能建立风格。</p>\n<p>在几张测试照片上学一次滤镜，选择就快了。不用 11 个全试一遍，就知道哪种适合人像、风景或者商品。</p>\n<h2 id=\"vintage-vs-sepia\">复古和棕褐有什么区别</h2>\n<p>复古和棕褐都有怀旧感，但强度不一样。棕褐是强烈的暖棕色调，复古是温和褪色，带一点淡淡的胶片感。</p>\n<p>棕褐适合历史照片、家庭回忆，以及所有应该感觉来自另一个年代的图片。棕色调一眼就能认出来，很大胆。</p>\n<p>复古适合日常照片和社交帖子，怀旧感应该是轻的。加了氛围，又没有棕褐那种厚重的棕色。</p>\n<p>同一张照片两个都试试，对照一下。合适的那个通常感觉就属于这个场景，不合适的那个像穿错了衣服。</p>\n<h2 id=\"grayscale-vs-noir\">黑白和黑白 Noir 有什么区别</h2>\n<p>黑白是去掉颜色，留下一张干净中性的黑白图片。真实平静，照片原样呈现，只是没有颜色。</p>\n<p>黑白 Noir 是去掉颜色，再加很强的对比。黑色更深，白色更亮，图片有了戏剧性、电影感的黑白质感。</p>\n<p>照片应该安静、纪实，选黑白。照片应该戏剧性，有强烈的阴影和明亮的高光，选黑白 Noir。</p>\n<p>两种都适合建筑、街头摄影和表情强烈的肖像。选哪个，看你是想要安静的黑白，还是戏剧性的黑白。</p>\n<h2 id=\"warm-vs-cool\">暖色和冷色有什么区别</h2>\n<p>暖色加了金色调，感觉阳光明媚、热情好客。适合人像、美食和风景，暖光让图片感觉很亲切。</p>\n<p>冷色加了蓝色调，感觉平静清爽。适合冬天场景、建筑和科技产品，冷色调看着现代干净。</p>\n<p>选哪个，看你想要什么氛围。雪景配暖色滤镜感觉不对，海滩日落配冷色滤镜，和自然的暖意打架。</p>\n<p>同一张照片两个都试试，对照一下。差别立刻就明显了，合适的那个通常感觉就属于这个场景。</p>\n<h2 id=\"matte-fade-vs-golden-hour\">哑光褪色和黄金时刻有什么区别</h2>\n<p>哑光褪色是柔化黑色，让照片带一点褪色的胶片质感。适合人像和生活方式照片，柔和梦幻的感觉正合适。</p>\n<p>黄金时刻模拟的是日落的暖光。加了一层金色光晕，适合风景、人像，以及所有在暖光下拍的照片。</p>\n<p>哑光褪色讲的是柔和，黄金时刻讲的是暖意。照片可以柔和而不暖，也可以暖而不柔和，两个滤镜服务的氛围不一样。</p>\n<p>梦幻人像选哑光褪色更好。日落风景选黄金时刻最合适，因为它加强的是本来就有的光线。</p>\n<h2 id=\"high-contrast-filter\">高对比和戏剧滤镜</h2>\n<p>高对比是加深阴影、提亮高光，给照片加冲击力。适合风景、建筑，以及所有看着发灰、没精神的照片。</p>\n<p>戏剧更进一步，阴影压得更深，带来阴郁、电影感的氛围。适合暴风雨的天空、城市夜景和大胆的编辑风格照片。</p>\n<p>两个滤镜对人像都可能太强。深阴影会让人脸显老、皮肤看着生硬，人像上用它们，要氛围确实需要才行。</p>\n<p>加完这两个滤镜检查高光。云朵和白色表面最先被裁掉，变成没有细节的死白。</p>\n<h2 id=\"invert-filter\">反色：最特别的一个</h2>\n<p>反色是把每种颜色翻成它的反色，照片变成底片。是这组滤镜里最特别的一个，适用范围很窄。</p>\n<p>大多数照片用反色只是图个新鲜，不是实用的修图。反色的人像看着很怪，反色的风景看着像外星。</p>\n<p>反色适合某个具体的创意目的：艺术效果、抢眼的图形，或者检查图片结构。一组照片里有一张反色图会很抢眼。</p>\n<p>别围绕反色建立统一风格。一组全是反色的照片让人困惑，正常照片里有一张反色图，反而能抓住眼球。</p>\n<h2 id=\"filters-for-portraits\">人像滤镜对比</h2>\n<p>复古、暖色和哑光褪色是最适合人像的滤镜。中等强度下加了氛围，又不改变人脸，这正是人像需要的。</p>\n<p>表情强烈的肖像适合黑白 Noir。戏剧性的黑白能突出眼睛和情绪，这就是它成为经典人像滤镜的原因。</p>\n<p>高对比和戏剧是大多数人脸最糟的滤镜。深阴影会让人脸显老、皮肤看着生硬。</p>\n<p>冷光下拍的人像可以用冷色滤镜，但也可能让皮肤看着苍白、没生气。定下来之前，先在脸上测试一下。</p>\n<h2 id=\"filters-for-landscapes\">风景滤镜对比</h2>\n<p>暖光风景最好的滤镜是黄金时刻。它加强日落的暖意，又不改变场景本身的性格。</p>\n<p>阴郁风景适合戏剧滤镜，暴风雨的天空很有气势。深阴影给云朵和山峦加了分量，场景有了电影感。</p>\n<p>柔和梦幻的风景适合复古和哑光褪色。雾蒙蒙的清晨或者安静的田野，配褪色的滤镜，有一种淡淡的怀旧感。</p>\n<p>暖色风景别用冷色滤镜。日落配蓝色调，和自然的暖意打架，结果看着像失误，而不是风格。</p>\n<h2 id=\"filters-for-food\">美食滤镜对比</h2>\n<p>暖色和黄金时刻是最好的美食滤镜。它们加强浓郁诱人的颜色，让菜看着新鲜诱人。</p>\n<p>低强度的复古也可以做美食，尤其适合质朴家常的感觉。褪色的感觉很适合家常菜和家庭食谱。</p>\n<p>冷色是最糟的美食滤镜。蓝色调让菜看着冷冰冰、没食欲，正好和美食照片的目标相反。</p>\n<p>加完滤镜检查红色。番茄、肉类和浆果在强滤镜下可能变成不自然的亮红色，食物反而看着更没食欲。</p>\n<h2 id=\"filters-for-products\">商品滤镜对比</h2>\n<p>商品需要准确的颜色，所以大多数滤镜都不适合。改变商品颜色的滤镜会误导买家、损害信任。</p>\n<p>低强度的高对比可以做商品，加了轮廓感，颜色基本没变。小幅提升能让商品从背景里跳出来。</p>\n<p>暖光下拍的商品，低强度的暖色也适合。它加强自然的暖意，又不改变商品颜色。</p>\n<p>商品目录要么不用滤镜，要么每张图用同一个温和的滤镜。一致性比风格重要，准确的颜色最重要。</p>\n<h2 id=\"choosing-consistent-look\">怎么选出统一风格</h2>\n<p>一组照片用同一个滤镜，能建立可辨认的风格。关注者还没看名字就认出了你的作品，这就是视觉身份。</p>\n<p>选定一个滤镜、一个强度，整组都用它。一组照片全是 50% 的复古滤镜，看着像精心打理过；滤镜混着用就显得杂乱。</p>\n<p>定下来之前，在不同类型的照片上都试一遍。适合风景的滤镜可能不适合人像，统一风格需要一个两种都适合的滤镜。</p>\n<p>滤镜选择要偶尔回顾一下。风格会变，去年感觉新鲜的滤镜，今年可能就过时了，作品进步了就更新它。</p>\n<h2 id=\"intensity-choices\">强度：真正的决定因素</h2>\n<p>滤镜选哪个，不如强度重要。100% 的复古滤镜和 50% 的复古滤镜看着像两种不同的修图，低一点通常更好看。</p>\n<p>先满强度看清滤镜的性格，再慢慢降低，直到感觉对了。预览实时更新，很快就能找到最舒服的点。</p>\n<p>人像用 40% 到 60% 的低强度通常最好。加了氛围，又不改变人脸，这正是人像需要的。</p>\n<p>风景用 60% 到 80% 的高强度也可以。场景能承受更强的效果，又不看着很假，因为没有肤色要保护。</p>\n<h2 id=\"mixing-filters\">一个信息流里混用滤镜</h2>\n<p>混用滤镜是最常见的统一性错误。一张复古、下一张戏剧、再下一张冷色，这样的信息流看着很乱、没计划。</p>\n<p>整组用一个滤镜，只调强度。复古风格的信息流，人像 40%、风景 60%，感觉还是统一的。</p>\n<p>某一张照片确实需要不同的滤镜，就当它是例外，不是习惯。一组复古信息流里有一张黑白 Noir 人像会很抢眼，五张就把风格打破了。</p>\n<p>有条件的话，拍摄之前就定好滤镜。带着一个滤镜的思路拍的一组照片，比事后随机加滤镜的一组看着更连贯。</p>\n<h2 id=\"trends-vs-timeless\">流行滤镜和不过时滤镜</h2>\n<p>滤镜风格和其他东西一样会流行。复古十年前很火，戏剧现在很火，极简自然的颜色永远不过时。</p>\n<p>要长久保存的作品，选不过时的滤镜。低强度的温和复古，十年后看着和今天一样好，强烈的戏剧滤镜可能很快就过时了。</p>\n<p>只活一天的社交帖子，用流行滤镜没问题。赶上当下风格的戏剧滤镜能提高互动，帖子被遗忘的速度比潮流过时的速度快得多。</p>\n<p>拿不准就选温和的。含蓄的滤镜永远不会错，它让照片本身撑场面，而不是让效果抢风头。</p>\n<h2 id=\"cheat-sheet\">选滤镜速查表</h2>\n<p>人像和日常照片用复古或者哑光褪色，强度 40% 到 60%。加了氛围，又不改变人脸。</p>\n<p>风景用黄金时刻或者戏剧滤镜，强度 60% 到 80%。加强光线和氛围，又不压过场景。</p>\n<p>暖光下的美食和商品用暖色滤镜，强度 40% 到 60%。加强诱人的颜色，又不改变颜色本身。</p>\n<p>建筑、街头摄影和戏剧性人像用黑白或者黑白 Noir。安静选黑白，戏剧选黑白 Noir。</p>\n<h2 id=\"filters-for-weddings\">婚礼照片滤镜对比</h2>\n<p>复古和哑光褪色是最好的婚礼滤镜。中等强度下加了柔和浪漫的感觉，又不改变人脸和白婚纱。</p>\n<p>暖光下的户外婚礼可以用黄金时刻。它加强日落的暖意，但也可能让婚纱带上黄色，所以白色要仔细检查。</p>\n<p>高对比和戏剧是最糟的婚礼滤镜。深阴影会让新人显老、婚纱变灰，正好和婚礼相册的目标相反。</p>\n<p>整套婚礼照片用同一个滤镜。每张照片共用同一个温和滤镜的相册，看着很专业；滤镜混着用，整场婚礼的感觉就散了。</p>\n<p>想看分步操作，请读<a href=\"/zh/blog/zenme-gei-zhaopian-jia-lvjing/\">怎么给照片加滤镜：5步做出统一风格</a>，完整指南请读<a href=\"/zh/blog/tupian-lvjing-zhinan/\">图片滤镜完全指南：11种滤镜用法与强度控制</a>。想精确调颜色而不是用预设，可以试试<a href=\"/zh/tiaozheng-tupian-baohedu/\">图片饱和度工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"统一风格的信息流用哪个滤镜好？","answer":"选定一个滤镜、一个强度，整组都用它，比如 50% 的复古滤镜。统一的滤镜能建立可辨认的风格，混着用看着很乱。定下来之前，先在人像和风景上都测试一下选好的滤镜。"},{"question":"复古滤镜和棕褐滤镜有什么区别？","answer":"棕褐是强烈的暖棕色调，感觉古老有历史感；复古是温和褪色，带一点淡淡的胶片感。棕褐适合历史照片和回忆，复古适合日常照片和社交帖子，怀旧感应该是轻的。"},{"question":"人像用黑白还是黑白 Noir？","answer":"安静纪实的人像用黑白，戏剧性强、表情强烈的人像用黑白 Noir。Noir 加了对比度，能突出眼睛和情绪；黑白原样呈现人脸。两种都适合性格鲜明的肖像。"},{"question":"用滤镜好，还是手动调饱和度好？","answer":"滤镜更快，一点就能得到协调的效果，适合社交帖子和快速修图。手动调饱和度能精确控制单一方面，适合商品照片和精细修图。风格用滤镜，准确用手动控制。"},{"question":"为什么我的滤镜照片每张看着都不一样？","answer":"很可能每张用了不同的滤镜或者强度。选定一个滤镜、一个强度给整组用，只按题材稍微调强度。一致的选择能在整个信息流里建立可辨认的风格。"},{"question":"滤镜能把不好的照片变好吗？","answer":"不能。滤镜改变的是氛围和颜色，修不好模糊、偏暗或者构图糟糕的照片。先修好亮度、对焦和构图，再选一个滤镜加强本来就不错的照片。"}];
